from collections import deque

def find_connected_components(grid, target_value):
    """Find connected components of target_value using N-connectivity"""
    components = []
    visited = set()

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r, c] == target_value and (r, c) not in visited:
                component = []
                queue = deque([(r, c)])
                while queue:
                    cr, cc = queue.popleft()
                    if (cr, cc) in visited:
                        continue
                    visited.add((cr, cc))
                    component.append((cr, cc))
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                            if grid[nr, nc] == target_value and (nr, nc) not in visited:
                                queue.append((nr, nc))
                components.append(component)

    return components

